1	import { Command } from "commander";
2	import { resolve } from "node:path";
3	import { discoverChanges, getChangeInfo } from "../lib/changes.js";
4	
5	export function createStatusCommand(): Command {
6	  const cmd = new Command("status");
7	
8	  cmd
9	    .description("Show artifact completion state for an OpenSpec change")
10	    .argument("[name]", "Change name (auto-selects if only one exists)")
11	    .option("--json", "Output as JSON")
12	    .option("--path <dir>", "Working directory", ".")
13	    .action(async (name: string | undefined, opts) => {
14	      const cwd = resolve(opts.path);
15	
16	      try {
17	        let changeName = name;
18	
19	        if (!changeName) {
20	          const changes = discoverChanges(cwd);
21	          if (changes.length === 0) {
22	            console.error("Error: No changes found.");
23	            process.exit(1);
24	          }
25	          if (changes.length > 1) {
26	            console.error(
27	              "Error: Multiple changes found. Specify one:\n" +
28	                changes.map((c) => `  - ${c}`).join("\n")
29	            );
30	            process.exit(1);
31	          }
32	          changeName = changes[0];
33	        }
34	
35	        const info = getChangeInfo(cwd, changeName);
36	
37	        if (opts.json) {
38	          const output = {
39	            changeName: info.name,
40	            schemaName: info.schemaName,
41	            state: info.state,
42	            isComplete: info.isComplete,
43	            artifacts: info.artifacts,
44	            taskGroups: info.taskGroups,
45	          };
46	          console.log(JSON.stringify(output, null, 2));
47	          return;
48	        }
49	
50	        // Human-readable output
51	        console.log(`Change: ${info.name} (state: ${info.state})`);
52	        console.log(`Schema: ${info.schemaName}`);
53	        console.log();
54	
55	        // Artifacts
56	        console.log("Artifacts:");
57	        for (const a of info.artifacts) {
58	          let icon: string;
59	          if (a.exists) {
60	            icon = "✓";
61	          } else if (a.blocked) {
62	            icon = "✗";
63	          } else if (a.ready) {
64	            icon = "○";
65	          } else {
66	            icon = "○";
67	          }
68	          let suffix = "";
69	          if (a.blocked && a.blockedBy.length > 0) {
70	            suffix = ` (blocked by: ${a.blockedBy.join(", ")})`;
71	          }
72	          console.log(`  ${icon} ${a.id} — ${a.description}${suffix}`);
73	        }
74	        console.log();
75	
76	        // Task groups
77	        if (info.taskGroups.length > 0) {
78	          console.log("Task Groups:");
79	          for (const tg of info.taskGroups) {
80	            const pct =
81	              tg.totalTasks > 0
82	                ? Math.round((tg.completedTasks / tg.totalTasks) * 100)
83	                : 0;
84	            console.log(
85	              `  ${tg.number}. ${tg.name}  ${tg.completedTasks}/${tg.totalTasks} (${pct}%)  [${tg.status}]`
86	            );
87	          }
88	          console.log();
89	        }
90	
91	        // Overall
92	        const overallPct =
93	          info.totalTasks > 0
94	            ? Math.round((info.completedTasks / info.totalTasks) * 100)
95	            : 0;
96	        console.log(
97	          `Overall: ${info.completedTasks}/${info.totalTasks} tasks (${overallPct}%) — ${info.isComplete ? "complete" : "in progress"}`
98	        );
99	      } catch (err: unknown) {
100	        const msg = err instanceof Error ? err.message : String(err);
101	        console.error(`Error: ${msg}`);
102	        process.exit(1);
103	      }
104	    });
105	
106	  return cmd;
107	}
